head.script:
scwin.tr1_onclick = function(e) {
    tabcontrol.setSelectedTabIndex(1);
    alert("2번째 탭으로 이동확인.");
};
scwin.tr2_onclick = function(e) {
    tabcontrol.setSelectedTabIndex("tabs2");
    //alert("ID값을 호출해도 인덱스로 먹히는지 확인한다.");	
};
scwin.tabs1_onclick = function() {
    alert("333");
};
scwin.__hasClass = function(id, className) {
    var classList = WebSquare.wUnit.getDomById($p.id + id).className;
    return classList.indexOf(className) >= 0;
}
scwin.__isEnableContent = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    return el.style.display == "block";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. Tab ID호출버튼을 클릭한다.
    //2. Click the Call Tab ID button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tr2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2. 2번째 Tab으로 이동됨이 확인된다.(Tab Id로 호출시 Tab Index로 호출됨이 확인된다.)
    //2. Move to the second tab is confirmed (Called with Tab Id confirms that it is called with Tab Index)
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass('tabcontrol_tab_tabs2', 'w2tabcontrol_active')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isEnableContent('tabcontrol_contents_content2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 06-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
